"""
flashcards.py: A command-line flashcard trainer with spaced-repetition scheduling.

Features:
- Deck management
- Spaced repetition with ease factor
- Review sessions with scheduler
- Progress/statistics saved to JSON

Author: Autonomous Agent
"""
import json
import os
import random
import datetime
from typing import List, Dict, Any, Optional

CONFIG_PATH = 'config.json'
PROGRESS_PATH = 'flashcard_progress.json'

# -------------------- Config utilities --------------------
def load_config(path: str = CONFIG_PATH) -> dict:
    with open(path, 'r') as f:
        return json.load(f)

def save_progress(progress: dict, path: str = PROGRESS_PATH):
    with open(path, 'w') as f:
        json.dump(progress, f, indent=2)

def load_progress(path: str = PROGRESS_PATH) -> dict:
    if not os.path.exists(path):
        return {}
    with open(path, 'r') as f:
        return json.load(f)

# -------------------- Data Models --------------------

class Card:
    def __init__(self, card_id: str, front: str, back: str):
        self.card_id = card_id
        self.front = front
        self.back = back

class CardState:
    def __init__(self, card_id: str, ease: float, interval: int, due: str, lapses: int = 0):
        self.card_id = card_id
        self.ease = ease
        self.interval = interval
        self.due = due
        self.lapses = lapses

    def to_dict(self):
        return dict(card_id=self.card_id, ease=self.ease, interval=self.interval,
                    due=self.due, lapses=self.lapses)
    @staticmethod
    def from_dict(d):
        return CardState(d['card_id'], d['ease'], d['interval'], d['due'], d.get('lapses',0))

class Deck:
    def __init__(self, name: str, cards: List[Card]):
        self.name = name
        self.cards = cards

# -------------------- Scheduler Logic --------------------

def next_review_date(days: int) -> str:
    return (datetime.date.today() + datetime.timedelta(days=days)).isoformat()

def compute_interval(interval: int, ease: float, correct: bool, config: dict) -> int:
    """Adjusts interval based on ease and correctness"""
    if correct:
        mult = ease
        new_int = int(max(interval * mult, config['min_interval']))
        return min(new_int, config['max_interval'])
    else:
        return 1  # Reset to 1 day after lapse

def update_ease(ease: float, correct: bool, config: dict) -> float:
    if correct:
        return min(ease + 0.15, config['max_ease'])
    else:
        return max(ease * config['lapse_penalty'], config['min_ease'])

# -------------------- Core Logic --------------------

def get_decks(config: dict) -> Dict[str, Deck]:
    decks = {}
    for deckname, deckrec in config['decks'].items():
        cs = []
        for idx, card in enumerate(deckrec['cards']):
            cs.append(Card(f"{deckname}:{idx}", card['front'], card['back']))
        decks[deckname] = Deck(deckname, cs)
    return decks

def initialize_progress(decks: Dict[str, Deck], config: dict) -> dict:
    progress = { 'decks': {}, 'last_session_time': None, 'stats': {}}
    for dname, deck in decks.items():
        progress['decks'][dname] = {}
        for card in deck.cards:
            progress['decks'][dname][card.card_id] = CardState(
                card.card_id,
                config['default_ease'],
                0,
                datetime.date.today().isoformat()
            ).to_dict()
    progress['stats'] = {
        k: 0 for k in config['stats_keys']
    }
    progress['last_session_time'] = None
    return progress

def find_due_cards(deck: Deck, states: Dict[str, Any]) -> List[Card]:
    """Find cards due today."""
    today = datetime.date.today().isoformat()
    due = []
    for card in deck.cards:
        s = states.get(card.card_id)
        if s and s['due'] <= today:
            due.append(card)
    return due

def find_new_cards(deck: Deck, states: Dict[str, Any], config: dict) -> List[Card]:
    newcards = []
    for card in deck.cards:
        s = states.get(card.card_id)
        if s and s['interval'] == 0:
            newcards.append(card)
    return newcards[:config['cards_per_new_session']]

def review_session(deck: Deck, states: Dict[str, Any], config: dict) -> Dict[str, Any]:
    """
    Run a review session. Simulate user answers at random for demo.
    Returns statistics about the session.
    """
    session_stats = {'reviewed': 0, 'correct': 0, 'wrong': 0, 'new_seen': 0}
    due = find_due_cards(deck, states)
    new = find_new_cards(deck, states, config)

    review_cards = due + new
    if config.get('randomize_reviews', False):
        random.shuffle(review_cards)
    for card in review_cards:
        state = CardState.from_dict(states[card.card_id])
        # Simulate answer: 85% chance correct for learning, 70% for review
        if state.interval == 0:
            correct = random.random() < 0.85
            session_stats['new_seen'] += 1
        else:
            correct = random.random() < 0.7
        session_stats['reviewed'] += 1
        if correct:
            session_stats['correct'] += 1
        else:
            session_stats['wrong'] += 1
            state.lapses += 1
        state.ease = update_ease(state.ease, correct, config)
        if correct:
            state.interval = compute_interval(state.interval or 1, state.ease, True, config)
        else:
            state.interval = 1
        state.due = next_review_date(state.interval)
        states[card.card_id] = state.to_dict()
    return session_stats

def update_stats(progress: dict, session_stats: dict):
    stats = progress['stats']
    stats['total_reviews'] = stats.get('total_reviews',0) + session_stats['reviewed']
    stats['correct'] = stats.get('correct',0) + session_stats['correct']
    stats['wrong'] = stats.get('wrong',0) + session_stats['wrong']
    stats['reviewed_today'] = session_stats['reviewed']
    stats['last_session_time'] = datetime.datetime.now().isoformat()
    # Can extend with more detailed analytics.

# -------------------- Progress/Statistics Display --------------------
def get_progress(progress: dict, deckname: str) -> dict:
    deckstats = progress['decks'][deckname]
    due = sum(1 for s in deckstats.values() if s['due'] <= datetime.date.today().isoformat())
    new = sum(1 for s in deckstats.values() if s['interval'] == 0)
    return {'due': due, 'new': new, 'total': len(deckstats)}

def print_stats(stats: dict):
    print("Session Stats:")
    for k, v in stats.items():
        print(f"  {k}: {v}")

def main():
    """Simulate a review session and print statistics."""
    config = load_config()
    decks = get_decks(config)
    progress = load_progress()
    if not progress or not progress.get('decks'):
        print("Initializing progress for all decks...")
        progress = initialize_progress(decks, config)
    for deckname, deck in decks.items():
        print(f"\n--- Deck: {deckname} ---")
        states = progress['decks'][deckname]
        prog = get_progress(progress, deckname)
        print(f"Progress: Due {prog['due']} | New {prog['new']} | Total {prog['total']}")
        session_stats = review_session(deck, states, config)
        update_stats(progress, session_stats)
        print_stats(session_stats)
    save_progress(progress)

if __name__ == '__main__':
    main()
